spec.expr:
sum by (method, code) (
  rate(rest_client_requests_total{
    job=~"$job",
    code="429"
  }[$__rate_interval])
)

topk(
  10,
  histogram_quantile(
    0.99,
    sum by (name, type, le) (
      rate(apiserver_admission_webhook_admission_duration_seconds_bucket[$__rate_interval])
    )
  )
)

topk(
  10,
  sum by (name, type) (
    rate(apiserver_admission_webhook_admission_duration_seconds_sum[$__rate_interval])
  )
  /
  sum by (name, type) (
    rate(apiserver_admission_webhook_admission_duration_seconds_count[$__rate_interval])
  )
)
